-- TNYPL V10 REAL VISITOR ANALYTICS
create table if not exists public.site_visits_v10(visitor_id text primary key,country_code text not null default 'XX',country_name text not null default 'Unknown',city text,first_seen timestamptz not null default now(),last_seen timestamptz not null default now(),page_views bigint not null default 1);
create table if not exists public.site_page_views_v10(id bigint generated by default as identity primary key,visitor_id text not null,page_path text not null default '/',viewed_at timestamptz not null default now());
alter table public.site_visits_v10 enable row level security;alter table public.site_page_views_v10 enable row level security;revoke all on public.site_visits_v10 from anon,authenticated;revoke all on public.site_page_views_v10 from anon,authenticated;
create or replace function public.track_site_visit_v10(visitor_id text,country_code text default 'XX',country_name text default 'Unknown',city text default null,page_path text default '/') returns void language plpgsql security definer set search_path=public as $$begin insert into public.site_visits_v10(visitor_id,country_code,country_name,city,first_seen,last_seen,page_views) values(visitor_id,upper(coalesce(nullif(country_code,''),'XX')),left(coalesce(nullif(country_name,''),'Unknown'),120),left(nullif(city,''),120),now(),now(),1) on conflict(visitor_id) do update set country_code=excluded.country_code,country_name=excluded.country_name,city=excluded.city,last_seen=now(),page_views=public.site_visits_v10.page_views+1;insert into public.site_page_views_v10(visitor_id,page_path) values(visitor_id,left(coalesce(nullif(page_path,''),'/'),300));end$$;
create or replace function public.get_public_site_stats_v10() returns jsonb language plpgsql security definer set search_path=public as $$declare registrations bigint:=0;verified bigint:=0;drafted bigint:=0;begin if to_regclass('public.players') is not null then execute 'select count(*) from public.players' into registrations;execute 'select count(*) from public.players where lower(coalesce(status,'')) in ('verified','approved','draft_eligible','draft eligible')' into verified;execute 'select count(*) from public.players where lower(coalesce(status,'')) in ('drafted','selected')' into drafted;end if;return jsonb_build_object('unique_visitors',(select count(*) from public.site_visits_v10),'page_views',(select count(*) from public.site_page_views_v10),'countries_reached',(select count(distinct country_code) from public.site_visits_v10 where country_code<>'XX'),'online_now',(select count(*) from public.site_visits_v10 where last_seen>=now()-interval '5 minutes'),'registrations',registrations,'verified_players',verified,'drafted_players',drafted,'countries',coalesce((select jsonb_agg(jsonb_build_object('country_code',country_code,'country_name',country_name,'visitors',visitors) order by visitors desc) from (select country_code,max(country_name) country_name,count(*) visitors from public.site_visits_v10 where country_code<>'XX' group by country_code order by count(*) desc limit 8)c),'[]'::jsonb));end$$;
select public.get_public_site_stats_v10();
